insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-routine-moniker-fresh-on-collision-s720','decision','A fresh moniker when both named ones are held','S720 conductor: handoff 716 named the routine''s next session SkyPetrel, which Sam''s plain S718 took, and handoff 720 named SkyCormorant for his next plain session. With both held, the routine''s run took an unused name, SkyEider, and the next free number, 720 (d-routine-takes-next-free-number-s713). A routine run never takes a name a plain session holds.',array['conductor','routine','monikers','handoffs'],'proposed','docs/session_721_handoff.md',null,null,'SkyEider (S720)','2026-11-24'),
('d-slimming-left-to-plain-session-s720','decision','The brief''s slimming items left to a plain session','S720 conductor: section 1''s slimming items and section 4 of COBIx''s brief on #3358 (Nov 23, 6:45 PM PT) go to a plain session, as its section 4 item 3 provides, under Sam''s routine prompt of 2026-11-17: "No new UI, tooling or governance work in conductor runs." The run stayed on collection.',array['conductor','routine','scope','cobix'],'proposed','docs/session_721_handoff.md; issue #3358',null,null,'SkyEider (S720)','2026-11-24'),
('d-piles-land-as-one-pr-s720','decision','Ten applied piles branches land as one PR','S720 conductor: the ten applied cheap-piles branches (College of the Sequoias, Clovis, East Los Angeles, Glendale, City College of San Francisco, Santa Monica, Ventura, Cabrillo, Contra Costa, El Camino; 95 records live) land as one PR, #3758 (claude/s720-piles-land), under the three-PR cap. City College of San Francisco''s own #3755 closes with a pointer to it.',array['conductor','merge-order','program-requirements','piles'],'proposed','#3758; #3755',null,null,'SkyEider (S720)','2026-11-24'),
('d-conductor-owns-applies-s720','decision','The conductor alone applies a plan','S720 conductor: workers never push kb/migrations/.apply. The conductor applies a plan only after its second reader''s APPLY verdict and a clean pre-read (N of N before-images, 0 confirms), then restores .apply to main''s value, so no merge carries a live trigger. Every S720 apply ran this way (p-one-apply-writer-per-branch-s720).',array['conductor','guarded-update','apply','rule-10'],'proposed','docs/reference/conductor_mode.md S720; #3758; #3759',null,null,'SkyEider (S720)','2026-11-24'),
('d-rios-reconcile-keeps-only-targets-s720','decision','A reconcile keeps only the records it was for','S720 conductor: each Los Rios reconcile (Sacramento City 45353709365, Cosumnes River 45355422235, Folsom Lake 45356831201) restamped records outside its targets. The branch kept only the records each was run for and put the rest back to main''s filing, S714''s precedent; Sacramento City''s 26 course-id gains wait for one reread.',array['program-requirements','reconcile','los-rios'],'proposed','#3759',null,null,'SkyEider (S720)','2026-11-24'),
('d-sbvc-without-32317-s720','decision','San Bernardino Valley''s paid read without 32317','S720 conductor: San Bernardino Valley''s paid read 45355976381 ran on 15 of its 16 pins, leaving out 32317 and its rule-B skip (f-sbvc-32317-rule-b-s720) rather than open a third review round, under Sam''s routine prompt of 2026-11-17: "Stop a review after two rounds and send what is left to Sam or COBIx." The skip and its test''s marking go to the follow-up.',array['program-requirements','san-bernardino-valley','review','lever'],'proposed','#3752',null,null,'SkyEider (S720)','2026-11-24'),
('d-fill-merged-after-local-main-merge-s720','decision','#3756 merged on a local merge with main','S720 conductor: #3756, the fill fix, merged as 35854487 once a local merge with main, which #3753 had just moved (949c3194), passed the gap tests; that local merge stood for the one update from main before its merge.',array['conductor','merge','program-requirements'],'proposed','#3756; #3753',null,null,'SkyEider (S720)','2026-11-24'),
('d-modesto-held-pooled-rule-s720','decision','Modesto Junior''s plan held for the pooled rule','S720 conductor: Modesto Junior''s plan (claude/s720-piles-modesto, plan s720j: 8 pool_figure_not_read named gaps, 13 held) stays unapplied, since 7 of its 8 pass today''s scorer once the parent figure is read as one pool (f-pool-figure-gaps-pass-when-pooled-s720). The pooled rule goes first; its 10 unread holds follow.',array['program-requirements','modesto-junior','piles','held'],'proposed','claude/s720-piles-modesto a6d019a4',null,null,'SkyEider (S720)','2026-11-24'),
('d-display-merged-without-main-update-s720','decision','#3754 merged without an update from main','S720 conductor: #3754, display build abf1f6396156, merged as 79a534fb without the one update from main before its merge: main had moved only by the daily dashboard commit 29927316, which touches none of its four files.',array['conductor','merge','display'],'proposed','#3754',null,null,'SkyEider (S720)','2026-11-24'),
('p-preread-catches-older-live-extraction-s720','pitfall','A pre-read catches an older live extraction','S720: East Los Angeles 02456''s live row sat on an older extraction than its committed record, so the pre-read held it and the plan went from 4 rows to 3. Plans since carry an on_live_run guard that holds a record whose live row is not on its committed run (Cabrillo 11293; Ventura 06973, 31298, 32834; Contra Costa 01400, 40761).',array['program-requirements','pre-read','guarded-update','piles'],'proposed','#3758 (claude/s720-piles-ela 32bb72a2)',null,null,'SkyEider (S720)','2026-11-24'),
('p-own-page-guard-shared-pages-s720','pitfall','A shared page is never a record''s own','S720: #3753''s second reader held Fullerton 35174, read from a page capture.json''s shared_pages lists with another program (the UC-transfer page, with 36798). A page shared_pages lists is never a record''s own (own_page reads shared_with); later plans ran the own-section guard and listed their shared pages in the receipt.',array['program-requirements','pages','guards','fullerton'],'proposed','#3753',null,null,'SkyEider (S720)','2026-11-24'),
('p-scorer-passes-guard-s720','pitfall','A record the scorer passes is never gap-filed','S720: #3753''s second reader found Fullerton 33680 and 42143 pass today''s scorer on their own records, under the printed floor, so they wait for a closed-list rescore in place of a named gap. Every later plan ran the scorer_passes guard; Ventura 30587 was held on it.',array['program-requirements','scorer','guards','named-gaps'],'proposed','#3753; #3758',null,null,'SkyEider (S720)','2026-11-24'),
('p-cap-lives-in-confidence-s720','pitfall','A named gap''s score cap lives in confidence()','S720: #3756''s keep_named_gaps recomputes a kept named gap through confidence() in kb/_program_named_gaps.py, so a cap set only in a plan is lost at the next reconcile. City College of San Francisco''s noted_section_cut_off cap moved into confidence(), and Contra Costa''s general education cap for degree_summary_ge_none went there too.',array['program-requirements','named-gaps','confidence','reconcile'],'proposed','#3758',null,null,'SkyEider (S720)','2026-11-24'),
('p-one-apply-writer-per-branch-s720','pitfall','One writer of .apply per branch','S720: on claude/s720-rios the conductor restored .apply (af952282) while the worker had a commit staged that still carried the plan''s .apply; its push fired migrate 45358888504, which the plan''s guard aborted with nothing written. One writer of .apply per branch; a worker pulls before it commits once the conductor has touched it.',array['conductor','apply','workers','guarded-update'],'proposed','#3759 5941ee65',null,null,'SkyEider (S720)','2026-11-24'),
('f-fill-refuses-cut-window-s720','fact','The scorer refuses an electives fill over a cut-off window','S720: #3756 (35854487) closed f-elective-fill-passes-cut-off-windows-s714 and f-rescore-drops-ge-units-not-read-gaps-s714: both electives fills read window_cut first and refuse with fill_refused naming section_cut_off, and a reconcile keeps a filed named gap its rule still names (keep_named_gaps). Dry run over 18,960 records: 15 passes taken away, none added.',array['program-requirements','scorer','reconcile','fix'],'proposed','#3756; docs/kb-notes/methodology-a-fill-must-check-what-it-fills.md',null,null,'SkyEider (S720)','2026-11-24'),
('f-pool-figure-gaps-pass-when-pooled-s720','fact','Pool-figure gaps pass when the parent figure is pooled','S720: 7 of Modesto Junior''s 8 pool_figure_not_read records pass today''s scorer once the parent figure over nested sub-blocks is read as one pool (as ''SELECT 6 UNITS MINIMUM FROM THE LISTS BELOW''). The pool_figure_not_read rows applied tonight at City College of San Francisco, Santa Monica, Ventura, El Camino and Fullerton may pass under that rule too.',array['program-requirements','named-gaps','modesto-junior','follow-up'],'proposed','claude/s720-piles-modesto a6d019a4',null,null,'SkyEider (S720)','2026-11-24'),
('f-cabrillo-recommended-lists-rule-s720','fact','Cabrillo''s recommended lists pass as choose-units','S720: Cabrillo''s reader dropped recommended_lists_only: with their ''Recommended'' blocks read as choose_units, today''s scorer passes 06352, 06380, 06381 and 44992 (06380''s 24 + 30 + 6 = 60), as it does 17 other Cabrillo records with that wording. A free rescore wording rule, left for the follow-up; the four are held (plan s720b).',array['program-requirements','cabrillo','wording-rules','follow-up'],'proposed','#3758 (claude/s720-piles-cabrillo fe792423)',null,null,'SkyEider (S720)','2026-11-24'),
('f-ccsf-own-option-reading-s720','fact','City College of San Francisco''s own-option reading','S720: City College of San Francisco''s six CNIT options (17614 to 17619) were filed one_option_of_shared_page. Keeping only each program''s own OPTION block, a reading that needs no page text, scores 17615 to 17618 equal; it is the follow-up''s free rule and would move those four from the named gap to passing (plan s720c).',array['program-requirements','city-college-of-san-francisco','wording-rules','follow-up'],'proposed','#3758 (claude/s720-piles-ccsf 599b7aa7)',null,null,'SkyEider (S720)','2026-11-24'),
('f-fullerton-shared-page-passing-s720','fact','Fullerton''s passing records on shared pages','S720: by #3753''s own-page test (a page capture.json''s shared_pages lists with another program is never a record''s own), 15 of Fullerton''s 296 passing records are not on their own page. Their passes stand; a later pass reads whether each read its own section.',array['program-requirements','fullerton','pages','follow-up'],'proposed','#3753',null,null,'SkyEider (S720)','2026-11-24'),
('f-scc-registry-file-changed-s720','fact','Santiago Canyon''s registry row changed under its pins','S720: Santiago Canyon''s registry row now names SCC_2026_2027_Catalog_accessible.pdf (1,165 pages), so paid read 45350768246 refused the three pins of the 374-page file before any extraction, nothing paid. Free page read 45352138673 moved 11909, 21673 and 42990 to PDF pp.406, 407 and 415 of the new file; the paid read waits.',array['program-requirements','santiago-canyon','registry','lever'],'proposed','#3752 (dee14b50)',null,null,'SkyEider (S720)','2026-11-24'),
('f-sbvc-32317-rule-b-s720','fact','San Bernardino Valley 32317 and rule B','S720: San Bernardino Valley 32317 takes a rule-B skip in the reader''s page checks, so paid read 45355976381 ran on 15 programs without it (d-sbvc-without-32317-s720). Its own page prints CDEV where the Program Course File lists CD (a course_renumbers entry for its nine codes). The skip and its test''s marking go to the follow-up PR.',array['program-requirements','san-bernardino-valley','reader','follow-up'],'proposed','#3752 (869fd94e)',null,null,'SkyEider (S720)','2026-11-24'),
('f-sacramento-city-course-id-gains-s720','fact','Sacramento City''s course-id gains await a reread','S720: Sacramento City''s reconcile 45353709365 restamped 34 records, none changing its verdict. 26 carry real course-id route gains and 4 kept their ge_units_not_read gap (04662, 17873, 17875, 42894); all 30 went back to main''s filing (35854487), so committed and live rows agree, and one Sacramento City reread posts them.',array['program-requirements','sacramento-city','reconcile','follow-up'],'proposed','#3759 (97da7e40, 7deeac04)',null,null,'SkyEider (S720)','2026-11-24'),
('m-collection-s720','milestone','S720''s collection: 126 records live at the checkpoint','S720 (2026-11-24), at the checkpoint''s writing: 126 program records live for $0.90 of paid reads: 101 named-gap records at eleven colleges (Fullerton 6, #3753; ten colleges'' piles, 95, in #3758), 9 section_cut_off gaps at Los Rios (#3759), 16 passing loads at Mendocino, Los Angeles Southwest and American River (#3752). Display build abf1f6396156 (#3754); the fill fix (#3756).',array['program-requirements','collection','milestone'],'proposed','#3753; #3754; #3756; #3758; #3759; #3752',null,null,'SkyEider (S720)','2026-11-24')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
